/**
 * Fetches the size of a given Wikipedia section (in characters of wikitext).
 *
 * @param {string} pageTitle - The title of the Wikipedia page.
 * @returns {Promise<number>} A promise that resolves with the size of the lead section in characters.
 */
async function getLeadSectionSize(pageTitle) {
    const url = this.urlUtils.getUrlForPage(pageTitle);
    try {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Failed to fetch page: ${response.statusText}`);
        }
        const html = await response.text();
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const leadSection = doc.querySelector('#mw-content-text > p');
        if (!leadSection) {
            throw new Error('No lead section found');
        }
        return leadSection.textContent.length;
    } catch (error) {
        console.error(error);
        return 0;
    }
}
