/**
 * Suggests a target title for the given source title and language pairs using the provided MT service.
 *
 * @param {string} sourceTitle - The source title for which to suggest a target title.
 * @param {Record<string, string>} languagePairs - A record mapping source languages to target languages.
 * @param {TranslationService} mtService - The machine translation service to use for generating suggestions.
 * @returns {Promise<string[]>} A promise that resolves to an array of suggested target titles.
 */
async function suggestTargetTitles(sourceTitle: string, languagePairs: Record<string, string>, mtService: TranslationService): Promise<string[]> {
    const suggestions: string[] = [];
    for (const [sourceLang, targetLang] of Object.entries(languagePairs)) {
        try {
            const translatedTitle = await mtService.translate(sourceTitle, sourceLang, targetLang);
            suggestions.push(translatedTitle);
        } catch (error) {
            console.error(`Failed to translate title from ${sourceLang} to ${targetLang}:`, error);
        }
    }
    return suggestions;
}
