private function computeChoices($choices) {
    // Compute the mode based on the properties of the choices
    $mode = 'default'; // Default mode
    if (isset($choices['property1'])) {
        $mode = 'mode1';
    } elseif (isset($choices['property2'])) {
        $mode = 'mode2';
    }

    // Validate the mode
    if (!in_array($mode, ['mode1', 'mode2', 'default'])) {
        throw new RuntimeException("Invalid mode: $mode");
    }

    return [
        'mode' => $mode,
        'buttons' => $this->getButtonsForMode($mode)
    ];
}

private function getButtonsForMode($mode) {
    switch ($mode) {
        case 'mode1':
            return ['button1', 'button2'];
        case 'mode2':
            return ['button3', 'button4'];
        default:
            return [];
    }
}
