class CodeMirrorLint {
    private rest: mw.Rest;
    private currentRequest: Promise<any> | null;

    constructor(rest: mw.Rest) {
        this.rest = rest;
        this.currentRequest = null;
    }

    private async execute(wikitext: string): Promise<any> {
        if (this.currentRequest) {
            this.currentRequest.catch(() => {});
            this.currentRequest = null;
        }

        try {
            const response = await this.rest.post('/v1/transform/wikitext/to/lint', {
                wikitext: wikitext,
                timeout: 30000 // Default timeout of 30 seconds
            });
            return response;
        } catch (error) {
            mw.log.warn('[CodeMirror] Lint request failed:', error);
            throw error;
        }
    }

    public async lint(doc: Document): Promise<void> {
        const wikitext = doc.toString();
        this.currentRequest = this.execute(wikitext);

        try {
            const result = await this.currentRequest;
            // Handle the lint result
        } catch (error) {
            // Handle the error
        } finally {
            this.currentRequest = null;
        }
    }
}
